/**
 * Real-store replay of a decision whose planner could not compare candidate prices: the identical request is served
 * from the store-owned decision cache, but the served plan never claims ranking authority.
 */
class LmdbReplayOnlyDecisionCacheTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String CACHE_HIT = "optimizer.pipelinePlanCacheHit";
	private static final String COST_COMPARISON = "optimizer.cascadesCostComparisonCompleteness";
	private static final List<String> PHYSICAL_METRICS = List.of("optimizer.joinAlgorithmHint",
			"optimizer.hashJoinBuildSide", "optimizer.physicalJoinImplementation", "optimizer.filterAlgorithmHint",
			"plannedIndexAccessMode", "plannedIndexName", "plannedLookupComponents", "plannedPhysicalImplementation");

	@Test
	void connectedTwoPatternJoinIsReplayedFromTheDecisionCacheWithoutCertificate(@TempDir File dataDir)
			throws Exception {
		// Default (auto) search: no wall-clock deadline, and the default Frontier provider leaves the comparison
		// unavailable for this join.
		String previousMode = System.clearProperty(LmdbCascadesOptimizer.MODE_PROPERTY);
		LmdbStore store = new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc").setBackgroundRawSamplingEnabled(false));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:a"), VF.createIRI("urn:p"), VF.createIRI("urn:b"));
				connection.add(VF.createIRI("urn:b"), VF.createIRI("urn:q"), VF.createIRI("urn:c"));
			}
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbPipelinePlanCache cache = pipelineCache(store);

			TupleExpr cold = plan(store);
			assertEquals("UNAVAILABLE_COST", cold.getStringMetricPlanned(COST_COMPARISON));
			assertEquals("false", cold.getStringMetricPlanned(CACHE_HIT));

			TupleExpr replayed = plan(store);
			assertEquals("true", replayed.getStringMetricPlanned(CACHE_HIT),
					"the identical request is replayed from the decision cache");
			assertEquals(physicalSignature(cold), physicalSignature(replayed));
			assertEquals("REPLAY_ONLY", replayed.getStringMetricPlanned("optimizer.planCacheAuthority"));
			assertEquals("BEST_KNOWN_UNBOUNDED", replayed.getStringMetricPlanned("optimizer.planCacheSearchBoundKind"));
			assertEquals("UNAVAILABLE_COST", replayed.getStringMetricPlanned(COST_COMPARISON));
			assertEquals(0L, decisionCache(cache).statistics().refreshUses());
			assertEquals(1, cache.entryCount());

			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:c"), VF.createIRI("urn:q"), VF.createIRI("urn:d"));
			}
			store.rebuildFrontierStatistics();
			TupleExpr afterCommit = plan(store);
			assertNotEquals("true", afterCommit.getStringMetricPlanned(CACHE_HIT),
					"new data re-plans a replay-only decision");
			TupleExpr replacement = plan(store);
			assertEquals("true", replacement.getStringMetricPlanned(CACHE_HIT),
					"the new decision replaced the family and is replayed for its own identical request");
			assertEquals(1, cache.entryCount());
			assertEquals(0L, decisionCache(cache).statistics().refreshUses());
		} finally {
			try {
				repository.shutDown();
			} finally {
				restore(LmdbCascadesOptimizer.MODE_PROPERTY, previousMode);
			}
		}
	}

	@Test
	void unavailableDecisionPlannedUnderAWallClockDeadlineIsNotRetained(@TempDir File dataDir) throws Exception {
		// Budgeted search always runs under a finite deadline. A deadline can cut the search even when the reported
		// completion is the work limit, so the decision is not a reproducible replay.
		String previousMode = System.setProperty(LmdbCascadesOptimizer.MODE_PROPERTY, "budgeted");
		String previousBudget = System.setProperty(LmdbCascadesOptimizer.BUDGET_PROPERTY, "1");
		LmdbStore store = new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc").setBackgroundRawSamplingEnabled(false));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:a"), VF.createIRI("urn:p"), VF.createIRI("urn:b"));
				connection.add(VF.createIRI("urn:b"), VF.createIRI("urn:q"), VF.createIRI("urn:c"));
			}
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbPipelinePlanCache cache = pipelineCache(store);

			TupleExpr cold = plan(store);
			assertEquals("UNAVAILABLE_COST", cold.getStringMetricPlanned(COST_COMPARISON));
			TupleExpr again = plan(store);
			assertEquals("false", again.getStringMetricPlanned(CACHE_HIT));
			assertNull(again.getStringMetricPlanned("optimizer.planCacheAuthority"));
			assertEquals(0, cache.entryCount());
		} finally {
			try {
				repository.shutDown();
			} finally {
				restore(LmdbCascadesOptimizer.MODE_PROPERTY, previousMode);
				restore(LmdbCascadesOptimizer.BUDGET_PROPERTY, previousBudget);
			}
		}
	}

	private static TupleExpr plan(LmdbStore store) throws Exception {
		var backing = store.getSailStore();
		try (SailSource source = backing.getExplicitSailSource().fork();
				SailDataset dataset = source.dataset(IsolationLevels.SNAPSHOT_READ)) {
			SailDatasetTripleTermSource triples = new SailDatasetTripleTermSource(backing.getValueFactory(), dataset);
			var statistics = backing.getEvaluationStatistics();
			EvaluationStrategy strategy = store.getEvaluationStrategyFactory()
					.createEvaluationStrategy(null, triples, statistics);
			LmdbQueryOptimizerPipeline pipeline = new LmdbQueryOptimizerPipeline(strategy, triples, statistics);
			return pipeline.optimize(new QueryRoot(join()), null, EmptyBindingSet.getInstance());
		}
	}

	private static LmdbPipelinePlanCache pipelineCache(LmdbStore store) {
		LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getSailStore()
				.getEvaluationStatistics();
		return statistics.estimatorRuntime().frontierSettings().pipelinePlanCache();
	}

	private static LmdbPlanDecisionCache decisionCache(LmdbPipelinePlanCache cache) throws Exception {
		var field = LmdbPipelinePlanCache.class.getDeclaredField("decisionCache");
		field.setAccessible(true);
		return (LmdbPlanDecisionCache) field.get(cache);
	}

	private static String physicalSignature(TupleExpr plan) {
		StringBuilder signature = new StringBuilder();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				signature.append(node.getSignature());
				for (String metric : PHYSICAL_METRICS) {
					String value = node.getStringMetricPlanned(metric);
					if (value != null) {
						signature.append(' ').append(metric).append('=').append(value);
					}
				}
				signature.append('\n');
				super.meetNode(node);
			}
		});
		return signature.toString();
	}

	private static Join join() {
		Join join = new Join(pattern("a", "urn:p", "b"), pattern("b", "urn:q", "c"));
		PlanningGraphDomains.capture(join, PlanningGraphDomain.defaultGraph());
		return join;
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of("_const_" + predicate, VF.createIRI(predicate), false,
				true), Var.of(object));
	}

	private static void restore(String name, String value) {
		if (value == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, value);
		}
	}
}
